package main

import (
	"encoding/base64"
	"strings"
)

// The owner's orb is the dot matrix of
// assets/orb-online-green-refined.gif, one frame per GIF frame. This file is
// generated by tools/mkorb.py, which the Windows workflow runs before it tests
// and builds, so every shipped dot and both green shades are the GIF's own
// pixels. The empty placeholder below keeps a bare checkout compiling until
// that step runs.
const (
	orbCols = 55
	orbRows = 50

	orbFrameMillis = 80

	orbGreenDim    = 0x0e7a4a
	orbGreenBright = 0x84ffbe

	orbFramesB64 = ``
)

var (
	orbDelays = []int{}

	orbFrames = decodeOrbFrames()
)

func decodeOrbFrames() [][]uint8 {
	joined := strings.ReplaceAll(orbFramesB64, "\n", "")
	if joined == "" {
		return nil
	}
	size := orbCols * orbRows
	frames := make([][]uint8, 0, 32)
	for _, part := range strings.Split(joined, "|") {
		raw, err := base64.StdEncoding.DecodeString(part)
		if err != nil || len(raw) < (size+3)/4 {
			return nil
		}
		levels := make([]uint8, size)
		for index := 0; index < size; index++ {
			levels[index] = (raw[index/4] >> (2 * uint(index%4))) & 0x3
		}
		frames = append(frames, levels)
	}
	return frames
}
